// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getLinksFavorites, createLinksFavorites } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const cursor = "999999999";
    const take = "-1";

    const favoritesGetResponse = await getLinksFavorites(client, headers, {"take": ["2"]}, 200);

    expect(favoritesGetResponse.statusCode, 'status code').toBe(200);
    expect(Array.isArray(getResponseValue(favoritesGetResponse, "response.links")), 'the accepted read returns a links array').toBe(true);
    expect(getResponseValue(favoritesGetResponse, "response.links").length, 'take=2 bounds the accepted page').toBeLessThanOrEqual(2);

    const favoritesPostResponse = await createLinksFavorites(client, headers, 405);

    expect(favoritesPostResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(favoritesPostResponse, "response"), 'a non-GET method is refused').toBe("Method not allowed.");
    expect(getResponseValue(favoritesPostResponse, "response.links"), 'a refused method returns no links').toBeNull();

    const [favoritesGet1Response, favoritesGet2Response, favoritesGet3Response] = await Promise.all([
        getLinksFavorites(client, headers, {"take": [take]}, 400),
        getLinksFavorites(client, headers, {"cursor": ["abc"]}, 400),
        getLinksFavorites(client, headers, {"cursor": [cursor]}, 400),
    ]);

    expect(favoritesGet1Response.statusCode, 'status code').toBe(400);
    expect(favoritesGet2Response.statusCode, 'status code').toBe(400);
    expect(favoritesGet3Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(favoritesGet1Response, "response.links"), 'a rejected negative take returns no links').toBeNull();
    expect(getResponseValue(favoritesGet2Response, "response.links"), 'a rejected unparseable cursor returns no links').toBeNull();
    expect(getResponseValue(favoritesGet3Response, "response.links"), 'a rejected unknown cursor returns no links').toBeNull();
});
